// Adds the twenty-second block to the day entry and updates the rifle README. Usage: node add_block22.js <sha256>
const fs = require('fs');
const path = require('path');
const hash = process.argv[2];
function patch(p, edit) {
  let s = fs.readFileSync(p, 'utf8');
  const crlf = s.includes('\r\n');
  if (crlf) s = s.split('\r\n').join('\n');
  s = edit(s);
  if (crlf) s = s.split('\n').join('\r\n');
  fs.writeFileSync(p, s);
}
function once(s, a, b) {
  if (s.split(a).length !== 2) { console.error('expected once: ' + a.slice(0, 70)); process.exit(1); }
  return s.split(a).join(b);
}
const block = fs.readFileSync(path.join(__dirname, 'block22.md'), 'utf8').split('\r\n').join('\n');
patch('C:/GameJam/Devlog/days/2026-11-12.md', s => {
  s = once(s, '## Design decisions\n', block + '## Design decisions\n');
  s = once(s, "two energy bars, the ammo screen's housing and pane, the magazine); not imported into Unreal yet |",
              "two energy bars, the ammo hologram's emitter and pane, the magazine); not imported into Unreal yet |");
  s = once(s, '- `media/2026-11-12/6_qte.png`: the spell QTE',
    '- `media/2026-11-12/14z_rifle_hologram.png`, `14za_rifle_hologram_first_person.png` (twenty-second block; Blender renders): the ammo display as a projected hologram over its emitter.\n- `media/2026-11-12/6_qte.png`: the spell QTE');
  return s;
});
patch('C:/GameJam/Glyphbound/SourceArt/Weapons/Rifle/README.md', s => {
  s = once(s, '17728E439D0085859397F16500775001DD3444596AE512F5D32DA9907AE58BD3', hash);
  s = once(s, "    - the ammo screen's housing on the rear of the sight's eyepiece, tilted 14° up towards the player;",
              "    - the ammo hologram's emitter at the foot of the sight's eyepiece: a low block with a glowing slit (the slit uses the atlas slot);");
  s = once(s, 'the hologram pane (32 × 16 mm, in the housing)', 'the hologram pane (38 × 19 mm, floating over the emitter, tilted 14° up towards the player)');
  s = once(s, '  - body, with the modelled rail, energy bars and screen housing;', '  - body, with the modelled rail, side panels, energy bars and hologram emitter;');
  s = once(s, "  - ammo display: a 2:1 hologram pane in the housing behind the sight's eyepiece.",
              "  - ammo display: a 2:1 hologram pane floating behind the sight's eyepiece, with its own material `M_RifleHolo`.");
  return s;
});
console.log('devlog and readme updated');

