420	void AGBGun::UpdateViewModel(float DeltaSeconds)
421	{
422		const FGBGunModelArt& Art = *ModelArt;
423	
424		// Trigger pull: 0 to full pitch and back over TriggerPullSeconds (linear in, linear out). A new shot restarts it.
425		if (VMTrigger && TriggerPullElapsed >= 0.f)
426		{
427			TriggerPullElapsed += DeltaSeconds;
428			if (TriggerPullElapsed >= TriggerPullSeconds)
429			{
430				TriggerPullElapsed = -1.f;
431				VMTrigger->SetRelativeRotation(FRotator::ZeroRotator);
432			}
433			else
434			{
435				const float Half = TriggerPullSeconds * 0.5f;
436				const float Frac = TriggerPullElapsed < Half
437					? TriggerPullElapsed / Half
438					: 1.f - (TriggerPullElapsed - Half) / Half;
439				VMTrigger->SetRelativeRotation(FRotator(TriggerPullPitch * Frac, 0.f, 0.f));
440			}
441		}
442	
443		// Shot kick and muzzle flash. The step is capped so a long frame still shows each one for at least one frame.
444		const float EffectStep = FMath::Min(DeltaSeconds, MaxEffectStep);
445		if (KickElapsed >= 0.f)
446		{
447			KickElapsed += EffectStep;
448			if (KickElapsed >= KickSeconds)
449			{
450				KickElapsed = -1.f;
451			}
452			ApplyKickPose();
453		}
454		if (MuzzleFlashElapsed >= 0.f)
