456			MuzzleFlashElapsed += EffectStep;
457			if (MuzzleFlashElapsed >= MuzzleFlashSeconds)
458			{
459				HideMuzzleFlash();
460			}
461		}
462	
463		// Magazine slide during reload, driven by GetReloadProgress: out (smoothstep), held, back in (smoothstep).
464		if (VMMagazine)
465		{
466			FVector Offset = FVector::ZeroVector;
467			if (bReloading)
468			{
469				const float Progress = GetReloadProgress();
470				if (Progress < 1.f / 3.f)
471				{
472					Offset = Art.MagazineOut * Smoothstep01(Progress * 3.f);
473				}
474				else if (Progress < 2.f / 3.f)
475				{
476					Offset = Art.MagazineOut;
477				}
478				else
479				{
480					Offset = Art.MagazineOut * (1.f - Smoothstep01((Progress - 2.f / 3.f) * 3.f));
481				}
482			}
483			VMMagazine->SetRelativeLocation(Art.MagazineRest + Offset);
484		}
485	
