487		EGBElement EnchantElement = EGBElement::Physical;
488		FName EnchantEffect = NAME_None;
489		FLinearColor GlowColor = Art.IdleGlow;
490		float Imbue = 0.f;
491		bool bEnchanted = false;
492		if (GetActiveEnchant(EnchantElement, EnchantEffect))
493		{
494			bEnchanted = true;
495			GlowColor = GBPlaceholder::ElementColor(static_cast<uint8>(EnchantElement));
496			Imbue = 1.f;
497			if (const AGBPlayerCharacter* Player = GetPlayerOwner())
498			{
499				if (const UGBStatusEffectComponent* Effects = Player->GetStatusEffects())
500				{
501					for (const FGBActiveStatusEffect& Active : Effects->GetActiveEffects())
502					{
503						if (Active.EffectId.ToString().StartsWith(TEXT("Enchant_")))
504						{
505							const float Left = Active.TotalDuration > KINDA_SMALL_NUMBER
506								? FMath::Clamp(Active.TimeRemaining / Active.TotalDuration, 0.f, 1.f)
507								: 1.f;
508							// The material lights a cell while 1 - ImbueU < ImbueRemaining, with ImbueU at the cell
509							// centres ((i + 0.5) / cells). Adding half a cell lights ceil(Left x cells) cells, so the
510							// last cell goes dark exactly when the enchant ends (owner, GDD v0.30), not half a cell early.
511							Imbue = Left > 0.f ? FMath::Min(1.f, Left + 0.5f / Art.EnergyCells) : 0.f;
512							break;
513						}
514					}
515				}
516			}
517		}
518		if (!bHasLastGlow || !LastGlowColor.Equals(GlowColor) || !FMath::IsNearlyEqual(LastImbueSent, Imbue))
519		{
