708	int32 AGBGun::AddSpareMagazines(int32 Count)
709	{
710		if (Count <= 0)
711		{
712			return 0;
713		}
714		const int32 Added = FMath::Clamp(GetMaxSpareMagazines() - Ammo.SpareMagazines, 0, Count);
715		if (Added > 0)
716		{
717			Ammo.SpareMagazines += Added;
718			NotifyEquipmentChanged();
719		}
720		return Added;
721	}
