725	void AGBGun::Reload()
726	{
727		if (bReloading || !bEquipped)
728		{
729			return;
730		}
731		if (Ammo.InMagazine >= GetMagazineSize() || Ammo.SpareMagazines <= 0)
732		{
733			return;
734		}
735		bReloading = true;
736		ReloadElapsed = 0.f;
737		ReloadDuration = FMath::Max(0.f, GetStat(GBStat::ReloadTime, 1.f));
738		NotifyEquipmentChanged();
739	}
