752	void AGBGun::FinishReload()
753	{
754		bReloading = false;
755		ReloadElapsed = 0.f;
756		if (Ammo.SpareMagazines > 0)
757		{
758			// The rounds left in the old magazine are lost (provisional, classic tactical style).
759			--Ammo.SpareMagazines;
760			Ammo.InMagazine = GetMagazineSize();
761		}
762		NotifyEquipmentChanged();
763	}
