// Adds the twenty-fifth block to the day entry. Usage: node add_block25.js "<package size text>"
const fs = require('fs');
const path = require('path');
const size = process.argv[2];
const p = 'C:/GameJam/Devlog/days/2026-11-12.md';
let s = fs.readFileSync(p, 'utf8');
