// The guns' energy bar blinks while the enchant has GunEnchantBlinkSeconds or less left (owner, 2026-11-12).
const fs = require('fs');
function patch(p, pairs) {
  let s = fs.readFileSync(p, 'utf8');
  const crlf = s.includes('\r\n');
  if (crlf) s = s.split('\r\n').join('\n');
  for (const [a, b] of pairs) {
    if (s.split(a).length !== 2) { console.error('expected once in ' + p + ': ' + a.slice(0, 70)); process.exit(1); }
    s = s.split(a).join(b);
  }
  if (crlf) s = s.split('\n').join('\r\n');
  fs.writeFileSync(p, s);
  console.log('patched', p);
}
const root = 'C:/GameJam/Glyphbound/';

patch(root + 'Source/Glyphbound/Weapons/GBGun.cpp', [
  [`	const FName WeakPointFlashFadeKey(TEXT("PistolWeakPointFlashFade"));
`, `	const FName WeakPointFlashFadeKey(TEXT("PistolWeakPointFlashFade"));
	// Energy bar: it blinks while the enchant has GunEnchantBlinkSeconds or less left, GunEnchantBlinkHz times per
	// second (Game.json; owner: "the light that shows the enchant's time starts to blink when 3 seconds are left").
	const FName EnchantBlinkSecondsKey(TEXT("GunEnchantBlinkSeconds"));
	const FName EnchantBlinkHzKey(TEXT("GunEnchantBlinkHz"));
`],
  [`	float Imbue = 0.f;
	bool bEnchanted = false;
`, `	float Imbue = 0.f;
	bool bEnchanted = false;
	bool bBarBlinking = false;
`],
  [`						Imbue = Left > 0.f ? FMath::Min(1.f, Left + 0.5f / Art.EnergyCells) : 0.f;
`, `						Imbue = Left > 0.f ? FMath::Min(1.f, Left + 0.5f / Art.EnergyCells) : 0.f;
						// Last seconds: the lit cells blink. The phase comes from the time left, so the bar is lit
						// as the blinking starts, each blink is half lit and half dark, and it ends dark.
						const UGBDataSubsystem* BlinkData = UGBDataSubsystem::Get(this);
						const float BlinkSeconds = BlinkData ? BlinkData->GetGameValue(EnchantBlinkSecondsKey, 3.f) : 3.f;
						const float BlinkHz = FMath::Max(0.1f, BlinkData ? BlinkData->GetGameValue(EnchantBlinkHzKey, 4.f) : 4.f);
						if (Active.TimeRemaining > 0.f && Active.TimeRemaining <= BlinkSeconds)
						{
							bBarBlinking = true;
							if (FMath::Frac(Active.TimeRemaining * BlinkHz) < 0.5f)
							{
								Imbue = 0.f;
							}
						}
`],
  [`	bLastGlowEnchanted = bEnchanted;
`, `	bLastGlowEnchanted = bEnchanted;
	bEnergyBarBlinking = bBarBlinking;
`],
]);

patch(root + 'Source/Glyphbound/Weapons/GBGun.h', [
  [`	float GetViewModelImbueSent() const { return LastImbueSent; }
`, `	float GetViewModelImbueSent() const { return LastImbueSent; }
	/** Whether the energy bar is in its last-seconds blink (the enchant is about to end). The value sent is 0 in the dark half of each blink. */
	bool IsViewModelEnergyBarBlinking() const { return bEnergyBarBlinking; }
`],
  [`	bool bLastGlowEnchanted = false;
`, `	bool bLastGlowEnchanted = false;
	bool bEnergyBarBlinking = false;
`],
]);

patch(root + 'Content/Data/Game.json', [
  [`		"PistolWeakPointFlashFade": 0.15,
`, `		"PistolWeakPointFlashFade": 0.15,
		"GunEnchantBlinkSeconds": 3,
		"GunEnchantBlinkHz": 4,
`],
]);

// Smoke: no blink at half the enchant; blinking once the time left is under the threshold.
const helper = `	static FGBAmmoState ReloadAmmoBefore;

	// Energy bar blink (the enchant's last seconds). SetEnchantTimeLeft moves the active weapon enchant's clock.
	static void SetEnchantTimeLeft(AGBPlayerCharacter* Player, float Seconds)
	{
		UGBStatusEffectComponent* Effects = Player->GetStatusEffects();
		if (!Effects)
		{
			return;
		}
		FName EnchantId = NAME_None;
		for (const FGBActiveStatusEffect& Active : Effects->GetActiveEffects())
		{
			if (Active.EffectId.ToString().StartsWith(TEXT("Enchant_")))
			{
				EnchantId = Active.EffectId;
				break;
			}
		}
		if (EnchantId.IsNone())
		{
			UE_LOG(LogGB, Error, TEXT("SMOKE enchant blink: no weapon enchant is active"));
			return;
		}
		Effects->SetTimeRemaining(EnchantId, Seconds);
	}

	static void CheckEnchantBlink(const TCHAR* Gun, const AGBGun* Item, bool bExpected, const TCHAR* When)
	{
		const bool bBlinking = Item->IsViewModelEnergyBarBlinking();
		UE_LOG(LogGB, Display, TEXT("SMOKE %s energy bar blinking=%d (%s)"), Gun, bBlinking ? 1 : 0, When);
		if (bBlinking != bExpected)
		{
			UE_LOG(LogGB, Error, TEXT("SMOKE %s energy bar blink FAILED: blinking=%d %s (expected %d)"), Gun, bBlinking ? 1 : 0, When, bExpected ? 1 : 0);
		}
	}
`;
function gunSteps(gun, Gun, check, doneAnchor) {
  return [
    // half bar: not blinking yet
    [`			UE_LOG(LogGB, Display, TEXT("SMOKE ${gun} half bar imbue=%.2f"), Imbue);
`, `			UE_LOG(LogGB, Display, TEXT("SMOKE ${gun} half bar imbue=%.2f"), Imbue);
			CheckEnchantBlink(TEXT("${gun}"), Gun, false, TEXT("at half the enchant"));
`],
    // after the kick check: wind the enchant to its last seconds
    [`				UE_LOG(LogGB, Error, TEXT("SMOKE ${gun} muzzle flash FAILED: visible=%d kick=%.2f right after a shot (expected visible and a kick)"), bVisible ? 1 : 0, Kick);
			}
`, `				UE_LOG(LogGB, Error, TEXT("SMOKE ${gun} muzzle flash FAILED: visible=%d kick=%.2f right after a shot (expected visible and a kick)"), bVisible ? 1 : 0, Kick);
			}
			SetEnchantTimeLeft(Player, 2.5f);
`],
    [doneAnchor, doneAnchor + `			if (const AGBGun* BlinkGun = ${check})
			{
				CheckEnchantBlink(TEXT("${gun}"), BlinkGun, true, TEXT("with 2 seconds left"));
			}
`],
  ];
}
patch(root + 'Source/Glyphbound/Core/GBDevCommands.cpp', [
  [`	static FGBAmmoState ReloadAmmoBefore;
`, helper],
  ...gunSteps('pistol', 'Pistol', 'Cast<AGBGun>(Player->GetEquipment()->GetActiveItem())',
    `		Add(54.95f + S, TEXT("pistol done: staff back in hand"), [](UWorld*, AGBPlayerCharacter* Player)
		{
`),
  ...gunSteps('rifle', 'Rifle', 'RifleInHand(Player)',
    `		Add(61.6f + S, TEXT("rifle done: staff back in hand"), [](UWorld*, AGBPlayerCharacter* Player)
		{
`),
]);

